import {newLanguageScene,renderLanguageScene} from './language-scene.mjs';
import {ownRecord} from './state-validation.mjs';
import {contextConcepts,contextFor,contextRounds,contextOptions} from './language-context-data.mjs';
import {mountLanguageAudio,stopLanguageAudio} from './language-audio.mjs';
export const newContext=()=>({page:'guide',step:0,choice:null,checked:false,hint:false});
export function validateContext(s){ownRecord(s,['page','step','choice','checked','hint']);if(!['guide','practice','close'].includes(s.page)||!Number.isInteger(s.step)||s.step<0||s.step>=contextRounds.length||![null,...contextConcepts.map(c=>c.id)].includes(s.choice)||typeof s.checked!=='boolean'||typeof s.hint!=='boolean'||s.checked&&!s.choice||s.page==='guide'&&(s.step!==0||s.choice!==null||s.checked||s.hint)||s.page==='close'&&(s.step!==5||s.choice!==null||s.checked||s.hint))throw Error('Invalid contextual language state');return {...s};}
export function checkContext(id,step,choice){const l=contextFor(id),r=contextRounds[step];if(!l||!Number.isInteger(step)||!r||!contextConcepts.some(c=>c.id===choice))throw Error('Invalid contextual answer');const i=contextConcepts.findIndex(c=>c.id===r.target),correct=choice===r.target;return {correct,feedback:(correct?'La etiqueta corresponde. ':'Puedes revisar la relación. ')+l.words[i]+' significa «'+contextConcepts[i].label+'». '+(r.kind==='match'?contextConcepts[i].hint:'La escena pide nombrar ese objeto, no todos los objetos que podrían servir aquí.')};}
const shapes={apple:'<path d="M60 39C24 19 18 61 34 82Q47 100 60 90Q77 100 89 78C106 43 86 22 60 39Z" fill="#b75b40"/><path d="M60 40L63 20M64 27Q80 8 91 20Q84 35 64 27" fill="#63834e"/>',book:'<path d="M60 35Q37 20 15 30V89Q38 78 60 95Q82 78 105 89V30Q83 20 60 35Z" fill="#fffdf4"/><path d="M60 35V95M25 43L49 45M25 56L49 58M72 45L96 43M72 58L96 56" fill="none"/>',bread:'<path d="M16 75C13 45 34 30 61 30S109 45 105 75Q60 96 16 75Z" fill="#d9b47a"/><path d="M36 40L29 61M58 36L51 59M81 40L74 61" fill="none"/>'};
export const contextPicture=id=>`<svg class="context-picture" viewBox="0 0 120 110" aria-hidden="true" focusable="false"><g stroke="#344d41" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">${shapes[id]}</g></svg>`;
const sceneDrawing=id=>{const backdrop=id==='book'?'<path d="M25 45H95V125H25ZM30 78H90M43 49V73M60 49V73M77 49V73" fill="#d7dfcc"/><path d="M105 120H275M120 120V150M260 120V150" fill="none"/>':id==='apple'?'<path d="M75 70Q160 5 245 70" fill="none"/><path d="M65 90H255L235 145H85Z" fill="#d9b47a"/><path d="M90 110H230M100 130H220" fill="none"/>':'<path d="M30 113H290M50 113V150M270 113V150" fill="none"/><ellipse cx="165" cy="107" rx="85" ry="15" fill="#fffdf4"/>';return `<svg class="context-scene-drawing" viewBox="0 0 320 165" aria-hidden="true" focusable="false"><g stroke="#344d41" stroke-width="3" stroke-linejoin="round">${backdrop}<g transform="translate(105 ${id==='apple'?15:10}) scale(.9)">${shapes[id]}</g></g></svg>`;};
export function renderContext(root,state,id,finish){
 stopLanguageAudio(root.ownerDocument);const l=contextFor(id),s=state.context??=newContext(),r=contextRounds[s.step];
 if(state.contextScene?.open){renderLanguageScene(root,state,id,finish,{picture:contextPicture,back:()=>{renderContext(root,state,id,finish);root.querySelector('#context-title')?.focus();}});return;}
 const launch=()=>{const b=root.ownerDocument.createElement('button');b.type='button';b.className='action secondary';b.id='context-build';b.textContent='Construir mi escena con etiquetas';root.querySelector('.context-studio').append(b);b.onclick=()=>{state.contextScene??=newLanguageScene();state.contextScene.open=true;renderContext(root,state,id,finish);root.querySelector('#scene-title')?.focus();};};
 const word=i=>`<span lang="${l.id}">${l.words[i]}</span>${l.pinyin?` <small lang="zh-Latn">${l.pinyin[i]}</small>`:''}`;
 const guide=`<div class="context-guide">${contextConcepts.map((c,i)=>`<div>${contextPicture(c.id)}<p>${c.label} → <strong>${word(i)}</strong></p></div>`).join('')}</div>`;
 const redraw=(focus='#context-title')=>{renderContext(root,state,id,finish);root.querySelector(focus)?.focus();};
 const header=`<section class="context-studio"><p class="eyebrow">${l.name} · recorrido 2 · 6–8 años con adulto</p><h4 id="context-title" tabindex="-1">Una cesta de palabras</h4>`;
 const bind=(sel,fn)=>root.querySelector(sel)?.addEventListener('click',fn);
 if(s.page==='guide'){
 root.innerHTML=header+`<p>Tres palabras nuevas. Primero conecta palabras con dibujos; después elige etiquetas para escenas. Puedes consultar la guía, pasar o parar.</p>${guide}<p>Usamos nombres de objetos, sin artículos ni frases. ${l.id==='zh'?'Caracteres simplificados y pinyin con tonos como apoyo escrito. ':''}No se evalúa pronunciación. El recorrido inicial conserva su propio progreso.</p><button type="button" class="action primary" id="context-start">Conectar palabra y dibujo</button></section>`;
 bind('#context-start',()=>{s.page='practice';redraw();});launch();mountLanguageAudio(root,id,[0,1,2]);return;
 }
 if(s.page==='close'){
 root.innerHTML=header+`<p>Has llegado al cierre; puedes haber pasado ejercicios. No es una puntuación ni una prueba de dominio.</p>${guide}<p><strong>Fuera de pantalla:</strong> dibuja una cesta con estos tres objetos. Escribe o señala una etiqueta con ayuda. Puedes consultar las palabras; no necesitas comida real ni repetir sonidos.</p><div class="controls"><button type="button" class="action secondary" id="context-again">Volver a explorar</button><button type="button" class="action primary" id="context-finish">Terminar por hoy</button></div></section>`;
 bind('#context-again',()=>{Object.assign(s,newContext());redraw();});bind('#context-finish',finish);launch();mountLanguageAudio(root,id,[0,1,2]);return;
 }
 const i=contextConcepts.findIndex(c=>c.id===r.target),result=s.checked?checkContext(id,s.step,s.choice):null,order=contextOptions(s.step);
 root.innerHTML=header+`<p>Encuentro ${s.step+1} de 6 · ${r.kind==='match'?'Conecta palabra y dibujo':'Elige una etiqueta en la escena'}</p>${r.kind==='match'?`<p class="context-prompt">¿Qué dibujo conectarías con <strong>${word(i)}</strong>?</p>`:`<figure class="context-scene">${sceneDrawing(r.target)}<figcaption><strong>${r.scene}</strong>. ${r.text}</figcaption></figure>`}<fieldset><legend>${r.kind==='match'?'Elige un dibujo; su nombre en español también ayuda':'Elige la palabra para el objeto señalado'}</legend><div class="context-options">${order.map(c=>`<button type="button" class="action secondary context-option" data-context-choice="${c.id}" aria-pressed="${s.choice===c.id}">${r.kind==='match'?contextPicture(c.id)+c.label:word(contextConcepts.indexOf(c))}</button>`).join('')}</div></fieldset><div class="controls"><button type="button" class="action primary" id="context-check">Revisar la conexión</button><button type="button" class="action secondary" id="context-retry">Reintentar</button><button type="button" class="action secondary" id="context-hint">Una pista</button></div><p id="context-feedback" role="status" tabindex="-1">${result?.feedback||''}</p><p id="context-hint-text" role="status" tabindex="-1">${s.hint?contextConcepts[i].hint+' En la guía, '+l.words[i]+' corresponde a '+contextConcepts[i].label+'.':''}</p><details><summary>Consultar las tres palabras nuevas</summary>${guide}</details><button type="button" class="action ${result?.correct?'primary':'secondary'}" id="context-next">${s.step===5?'Ir al cierre práctico':result?.correct?'Siguiente encuentro':'Pasar este encuentro'}</button><p class="quiet">Puedes pausar arriba. Consultar, pasar y volver a probar forman parte de explorar.</p></section>`;
 root.querySelectorAll('[data-context-choice]').forEach(b=>b.onclick=()=>{s.choice=b.dataset.contextChoice;s.checked=false;redraw(`[data-context-choice="${s.choice}"]`);});
 bind('#context-check',()=>{if(!s.choice){const f=root.querySelector('#context-feedback');f.textContent='Elige una opción o consulta la guía.';f.focus();return;}s.checked=true;redraw('#context-feedback');});
 bind('#context-retry',()=>{s.choice=null;s.checked=false;s.hint=false;redraw();});bind('#context-hint',()=>{s.hint=true;redraw('#context-hint-text');});
 bind('#context-next',()=>{if(s.step===5)s.page='close';else s.step++;s.choice=null;s.checked=false;s.hint=false;redraw();});launch();mountLanguageAudio(root,id,[i]);
}
